import{_ as c,I as n,o as r,c as a,j as o,a as d,J as i,ak as l}from"./chunks/framework.D6lxc04_.js";const x=JSON.parse('{"title":"Rendering 渲染","description":"","frontmatter":{"title":"Rendering 渲染","prev":false,"next":false},"headers":[],"relativePath":"posts/docs/rendering/index.md","filePath":"posts/docs/rendering/index.md","lastUpdated":1778663550000}'),s={name:"posts/docs/rendering/index.md"},f={id:"渲染模块",tabindex:"-1"};function u(h,e,m,b,p,g){const t=n("Badge");return r(),a("div",null,[o("h1",f,[e[0]||(e[0]=d("渲染模块 ",-1)),i(t,{type:"tip",text:"26.1 only"}),e[1]||(e[1]=d()),e[2]||(e[2]=o("a",{class:"header-anchor",href:"#渲染模块","aria-label":"Permalink to “渲染模块”"},"​",-1))]),e[3]||(e[3]=l('<div class="warning custom-block"><p class="custom-block-title">Availability</p><p>本模块<strong>仅</strong>在 Minecraft <strong>26.1</strong> 版本中存在。所有更早的版本（1.21.1 至 1.21.11）均不包含此模块。</p></div><p>包 <code>dev.anvilcraft.lib.v2.rendering</code> 提供了泛光（Bloom）后处理效果以及一套通用的 UBO（Uniform Buffer Object）布局定义框架，并通过 Mixin 集成到 Minecraft 的 GUI 渲染和主渲染流程中。</p><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to “文档索引”">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="./bloom.html">泛光后处理</a></td><td><code>BloomPostEffect</code>、<code>BloomRenderCallback</code>、多 Pass 处理链</td></tr><tr><td><a href="./ubo.html">UBO 框架</a></td><td><code>UboObject</code>、<code>UboLayoutDefinition</code>、<code>UboLayoutEntry</code>、STD140 布局</td></tr><tr><td><a href="./integration.html">渲染集成</a></td><td><code>ALRendering</code>、Mixin、<code>LibGuiElementRenderState</code>、着色器管线</td></tr><tr><td><a href="./sdf.html">SDF 2D 图形</a></td><td><code>SdfGraphics</code>、<code>Sdf2d</code>、<code>SdfParameters</code>、7 种图形类型</td></tr><tr><td><a href="./cachedber.html">Cached BlockEntity 渲染</a></td><td>CachedBER 管线、CachedBlockEntityRenderer、RebuildTask</td></tr></tbody></table><h2 id="模块结构" tabindex="-1">模块结构 <a class="header-anchor" href="#模块结构" aria-label="Permalink to “模块结构”">​</a></h2><ul><li><strong>主类</strong>: <code>AnvilLibRendering</code>（原 <code>ALRendering</code>） — ALR→AnvilLib 重命名，模组入口，创建管线，注册事件</li><li><strong>CachedBER 管线</strong>: <code>cachedber</code> 包 — <code>CachedBlockEntityRenderingPipeline</code>、<code>CachedRenderingChunk</code>、<code>RebuildTask</code>、 <code>CachedBlockEntityRenderDispatcher</code>、<code>CachedBlockEntityRenderer&lt;T,S&gt;</code></li><li><strong>后处理</strong>: <code>BloomPostEffect</code> — 泛光效果多 Pass 处理链，<code>ALRPostEffects</code> — 泛光后处理单例、<code>runBloomDraws()</code></li><li><strong>UBO 框架</strong>: <code>foundation.buffers.ubo</code> 包（<code>foundation/</code> 重组后从 <code>foundation.ubo</code> 迁移） — 类型安全的 ST140 布局定义</li><li><strong>Foundation 重组</strong>: <code>foundation/</code> 目录重组：<code>buffers/ubo/</code>、新 <code>compound/</code> 包（<code>CompoundSubmitNode</code>）、新 <code>ALRMeshSorting.java</code>、<code>BloomSubmitNodeStorage.java</code>；<code>buffers/</code> 下新增 <code>EmptyBufferSource</code>、<code>EmptyOutlineBufferSource</code>、 <code>EmptyVertexConsumer</code>、<code>FullyBufferedBufferSource</code>、<code>VertexBufferHost</code></li><li><strong>渲染类型</strong>: <code>extension/ALRRenderTypeExtension.java</code> — 渲染类型扩展，<code>mixins/RenderTypeMixin.java</code> — 渲染类型 Mixin</li><li><strong>着色器</strong>: <code>blit.vsh</code>, <code>blur.fsh</code>, <code>apply_bloom.fsh</code>, <code>down_sample.fsh</code>, <code>up_sample.fsh</code></li><li><strong>Mixin</strong>: <code>GuiRendererMixin</code>, <code>MinecraftMixin</code> — 渲染流程嵌入</li></ul><blockquote><p>该模块仅在 Minecraft 26.1 版本中存在（<code>module.rendering</code>）。</p></blockquote><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>泛光效果依赖大量 RenderTarget 创建，限定客户端环境</li><li>所有 GPU 资源由 <code>GpuDevice</code> 创建，生命周期跟随 <code>BloomPostEffect</code> 实例</li></ul>',9))])}const R=c(s,[["render",u]]);export{x as __pageData,R as default};
